import Mathlib

/- II. (20 points) Four real numbers $a, b, c, d$ satisfy:
(1) $a \geqslant b \geqslant c \geqslant d$;
(2) $a+b+c+d=9$;
(3) $a^{2}+b^{2}+c^{2}+d^{2}=21$.

Prove: (1) $a+b \geqslant 5$;
(2) $ab - cd \geqslant 2$. -/
theorem algebra_314716 {a b c d : ℝ} (h1 : a ≥ b ∧ b ≥ c ∧ c ≥ d)
    (h2 : a + b + c + d = 9) (h3 : a^2 + b^2 + c^2 + d^2 = 21) :
    a + b ≥ 5 ∧ a * b - c * d ≥ 2 := by

